"use client"

import * as React from "react"
import { Combobox as ComboboxPrimitive } from "@base-ui/react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import { ChevronDownIcon, XIcon, CheckIcon } from "lucide-react"

type ComboboxVariant = "outline" | "subtle" | "ghost"
type ComboboxSize = "xs" | "sm" | "md" | "lg"

const ComboboxContext = React.createContext<{
  variant: ComboboxVariant
  size: ComboboxSize
}>({
  variant: "outline",
  size: "md",
})

function useComboboxVariant() {
  return React.useContext(ComboboxContext).variant
}

function useComboboxSize() {
  return React.useContext(ComboboxContext).size
}

function Combobox<TItem, TMultiple extends boolean | undefined = undefined>({
  variant = "outline",
  size = "md",
  ...props
}: ComboboxPrimitive.Root.Props<TItem, TMultiple> & {
  variant?: ComboboxVariant
  size?: ComboboxSize
}) {
  return (
    <ComboboxContext.Provider value={{ variant, size }}>
      <ComboboxPrimitive.Root {...props} />
    </ComboboxContext.Provider>
  )
}

function ComboboxValue({ ...props }: ComboboxPrimitive.Value.Props) {
  return <ComboboxPrimitive.Value data-slot="combobox-value" {...props} />
}

function ComboboxTrigger({
  className,
  children,
  ...props
}: ComboboxPrimitive.Trigger.Props) {
  return (
    <ComboboxPrimitive.Trigger
      data-slot="combobox-trigger"
      className={cn(
        "data-disabled:opacity-50 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    >
      {children}
      {/* chevron follows the input text: placeholder color while empty,
          value color once the input has content (placeholder no longer shown) */}
      <ChevronDownIcon className="pointer-events-none size-4 text-[color-mix(in_oklch,var(--secondary-foreground),var(--background)_52%)] group-has-[input:not(:placeholder-shown)]/input-group:text-secondary-foreground dark:text-[color-mix(in_oklch,var(--secondary-foreground),var(--background)_37%)] dark:group-has-[input:not(:placeholder-shown)]/input-group:text-secondary-foreground" />
    </ComboboxPrimitive.Trigger>
  )
}

function ComboboxClear({ className, ...props }: ComboboxPrimitive.Clear.Props) {
  return (
    <ComboboxPrimitive.Clear
      data-slot="combobox-clear"
      render={<InputGroupButton variant="ghost" size="icon-xs" />}
      className={cn(className)}
      {...props}
    >
      <XIcon className="pointer-events-none" />
    </ComboboxPrimitive.Clear>
  )
}

function ComboboxInput({
  className,
  children,
  disabled = false,
  showTrigger = true,
  showClear = false,
  ...props
}: ComboboxPrimitive.Input.Props & {
  showTrigger?: boolean
  showClear?: boolean
}) {
  const variant = useComboboxVariant()
  const size = useComboboxSize()
  return (
    <InputGroup
      variant={variant}
      size={size}
      className={cn(
        "w-auto data-[size=lg]:rounded-lg data-[size=md]:rounded-md data-[size=sm]:rounded-md data-[size=xs]:rounded-sm data-[variant=outline]:transition-shadow data-[variant=outline]:duration-150",
        className
      )}
    >
      <ComboboxPrimitive.Input
        render={
          <InputGroupInput
            disabled={disabled}
            // combobox uses text-base at lg (InputGroup's lg is text-lg)
            className="group-data-[size=lg]/input-group:text-base!"
          />
        }
        {...props}
      />
      <InputGroupAddon align="inline-end" className="pr-3">
        {showTrigger && (
          <InputGroupButton
            size="icon-xs"
            variant="ghost"
            render={<ComboboxTrigger />}
            data-slot="input-group-button"
            className={cn(
              "group-has-data-[slot=combobox-clear]/input-group:hidden data-pressed:bg-transparent",
              size === "xs"
                ? "size-4 rounded-2xs [&_svg]:size-3.5!"
                : size === "lg"
                  ? "size-5 rounded-2xs [&_svg]:size-4.5!"
                  : "size-4.5 rounded-2xs [&_svg]:size-4!"
            )}
            disabled={disabled}
          />
        )}
        {showClear && (
          <ComboboxClear
            disabled={disabled}
            className={
              size === "xs"
                ? "[&_svg]:size-3.5!"
                : size === "lg"
                  ? "[&_svg]:size-4.5!"
                  : "[&_svg]:size-4!"
            }
          />
        )}
      </InputGroupAddon>
      {children}
    </InputGroup>
  )
}

const comboboxContentRadiusClasses: Record<ComboboxSize, string> = {
  xs: "rounded-md",
  sm: "rounded-lg",
  md: "rounded-xl",
  lg: "rounded-xl",
}

function ComboboxContent({
  className,
  side = "bottom",
  sideOffset = 6,
  align = "start",
  alignOffset = 0,
  anchor,
  ...props
}: ComboboxPrimitive.Popup.Props &
  Pick<
    ComboboxPrimitive.Positioner.Props,
    "side" | "align" | "sideOffset" | "alignOffset" | "anchor"
  >) {
  const size = useComboboxSize()
  return (
    <ComboboxPrimitive.Portal>
      <ComboboxPrimitive.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        anchor={anchor}
        className="isolate z-50"
      >
        <ComboboxPrimitive.Popup
          data-slot="combobox-content"
          data-chips={!!anchor}
          className={cn(
            "group/combobox-content relative max-h-(--available-height) w-(--anchor-width) max-w-(--available-width) min-w-[calc(var(--anchor-width)+--spacing(7))] origin-(--transform-origin) overflow-hidden rounded-xl bg-card text-muted-foreground shadow-elevation-xl duration-100 data-[chips=true]:min-w-(--anchor-width) data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 *:data-[slot=input-group]:m-1 *:data-[slot=input-group]:mb-0 *:data-[slot=input-group]:h-8 *:data-[slot=input-group]:border-input/30 *:data-[slot=input-group]:bg-input/30 *:data-[slot=input-group]:shadow-none data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
            comboboxContentRadiusClasses[size],
            className
          )}
          {...props}
        />
      </ComboboxPrimitive.Positioner>
    </ComboboxPrimitive.Portal>
  )
}

function ComboboxList({ className, ...props }: ComboboxPrimitive.List.Props) {
  const variant = useComboboxVariant()
  return (
    <ComboboxPrimitive.List
      data-slot="combobox-list"
      data-variant={variant}
      className={cn(
        "no-scrollbar max-h-[min(calc(--spacing(72)---spacing(9)),calc(var(--available-height)---spacing(9)))] scroll-fade scroll-py-1 overflow-y-auto overscroll-contain p-1 data-empty:p-0",
        className
      )}
      {...props}
    />
  )
}

const comboboxItemSizeClasses: Record<ComboboxSize, string> = {
  xs: "py-1 pl-2 text-sm rounded-sm",
  sm: "py-1.5 pl-2 text-base rounded-md",
  md: "py-2 pl-2 text-base rounded-lg",
  lg: "py-2.75 pl-2.5 text-lg rounded-lg",
}

function ComboboxItem({
  className,
  children,
  ...props
}: ComboboxPrimitive.Item.Props) {
  const size = useComboboxSize()
  return (
    <ComboboxPrimitive.Item
      data-slot="combobox-item"
      className={cn(
        "not-data-[variant=destructive]:focus:**:text-secondaey-foreground relative mb-px flex w-full cursor-default items-center gap-2 rounded-md py-1.5 pr-8 pl-2 text-base text-secondary-foreground outline-hidden select-none last:mb-0 focus:bg-accent focus:text-secondary-foreground aria-selected:bg-secondary! data-highlighted:bg-secondary data-highlighted:text-secondary-foreground data-highlighted:active:bg-secondary data-highlighted:active:text-secondary-foreground data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        comboboxItemSizeClasses[size],
        className
      )}
      {...props}
    >
      {children}
      <ComboboxPrimitive.ItemIndicator
        render={
          <span className="pointer-events-none absolute top-1/2 right-2 flex size-4 -translate-y-1/2 items-center justify-center" />
        }
      >
        <CheckIcon className="pointer-events-none" />
      </ComboboxPrimitive.ItemIndicator>
    </ComboboxPrimitive.Item>
  )
}

function ComboboxGroup({ className, ...props }: ComboboxPrimitive.Group.Props) {
  return (
    <ComboboxPrimitive.Group
      data-slot="combobox-group"
      className={cn("p-1", className)}
      {...props}
    />
  )
}

function ComboboxLabel({
  className,
  ...props
}: ComboboxPrimitive.GroupLabel.Props) {
  return (
    <ComboboxPrimitive.GroupLabel
      data-slot="combobox-label"
      className={cn(
        "py-1.5 pr-2 pl-1.5 text-sm leading-base font-medium tracking-normal text-accent-foreground",
        className
      )}
      {...props}
    />
  )
}

function ComboboxCollection({ ...props }: ComboboxPrimitive.Collection.Props) {
  return (
    <ComboboxPrimitive.Collection data-slot="combobox-collection" {...props} />
  )
}

function ComboboxEmpty({ className, ...props }: ComboboxPrimitive.Empty.Props) {
  return (
    <ComboboxPrimitive.Empty
      data-slot="combobox-empty"
      className={cn(
        "hidden w-full justify-center py-2 text-center text-sm text-secondary-foreground group-data-empty/combobox-content:flex",
        className
      )}
      {...props}
    />
  )
}

function ComboboxSeparator({
  className,
  ...props
}: ComboboxPrimitive.Separator.Props) {
  return (
    <ComboboxPrimitive.Separator
      data-slot="combobox-separator"
      className={cn("pointer-events-none mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  )
}

// per-variant min-height (outline is 2px shorter for the shadow ring)
const comboboxChipsMinHClasses: Record<
  ComboboxVariant,
  Record<ComboboxSize, string>
> = {
  outline: {
    xs: "min-h-5.5!",
    sm: "min-h-6.5!",
    md: "min-h-7.5!",
    lg: "min-h-9.5!",
  },
  subtle: { xs: "min-h-6!", sm: "min-h-7!", md: "min-h-8!", lg: "min-h-10!" },
  ghost: { xs: "min-h-6!", sm: "min-h-7!", md: "min-h-8!", lg: "min-h-10!" },
}

const comboboxChipsSizeClasses: Record<ComboboxSize, string> = {
  xs: "text-sm rounded-sm",
  sm: "text-sm rounded-md",
  md: "text-sm rounded-md",
  lg: "text-base rounded-lg",
}

function ComboboxChips({
  className,
  ...props
}: React.ComponentPropsWithRef<typeof ComboboxPrimitive.Chips> &
  ComboboxPrimitive.Chips.Props) {
  const variant = useComboboxVariant()
  const size = useComboboxSize()
  return (
    <ComboboxPrimitive.Chips
      data-slot="combobox-chips"
      data-variant={variant}
      data-size={size}
      className={cn(
        "flex flex-wrap items-center gap-1 rounded-lg bg-clip-padding px-2.5 text-sm transition-colors has-aria-invalid:ring-3 has-aria-invalid:ring-destructive/20 has-data-[slot=combobox-chip]:px-1 dark:has-aria-invalid:ring-destructive/40",
        // outline variant
        "data-[variant=outline]:bg-background data-[variant=outline]:py-0.5 data-[variant=outline]:shadow-default data-[variant=outline]:transition-shadow data-[variant=outline]:duration-150 data-[variant=outline]:hover:shadow-raised data-[variant=outline]:has-[[data-slot=combobox-chip-input]:focus-visible]:shadow-raised",
        // subtle variant
        "data-[variant=subtle]:bg-secondary data-[variant=subtle]:py-0.75 data-[variant=subtle]:has-[[data-slot=combobox-chip-input]:focus-visible]:shadow-raised",
        // ghost variant
        "data-[variant=ghost]:bg-transparent data-[variant=ghost]:py-0.75 data-[variant=ghost]:has-[[data-slot=combobox-chip-input]:focus-visible]:bg-background",
        // size
        comboboxChipsMinHClasses[variant][size],
        comboboxChipsSizeClasses[size],
        className
      )}
      {...props}
    />
  )
}

const comboboxChipSizeClasses: Record<ComboboxSize, string> = {
  xs: "h-5 pl-1.5 text-xs",
  sm: "h-5 pl-1.5 text-xs",
  md: "h-6 pl-1.5 text-sm",
  lg: "h-7 pl-2 text-base has-data-[slot=combobox-chip-remove]:pr-1.5",
}

function ComboboxChip({
  className,
  children,
  showRemove = true,
  ...props
}: ComboboxPrimitive.Chip.Props & {
  showRemove?: boolean
}) {
  const variant = useComboboxVariant()
  const size = useComboboxSize()
  return (
    <ComboboxPrimitive.Chip
      data-slot="combobox-chip"
      data-variant={variant}
      data-size={size}
      className={cn(
        "flex h-[calc(--spacing(6))] w-fit items-center justify-center gap-1 rounded-sm px-1.5 text-sm leading-base font-normal tracking-normal whitespace-nowrap text-secondary-foreground has-disabled:pointer-events-none has-disabled:cursor-not-allowed has-disabled:opacity-50 has-data-[slot=combobox-chip-remove]:pr-1 data-[variant=ghost]:bg-secondary data-[variant=outline]:bg-secondary data-[variant=subtle]:bg-card data-[variant=subtle]:shadow-default data-[variant=subtle]:hover:shadow-raised",
        comboboxChipSizeClasses[size],
        className
      )}
      {...props}
    >
      {children}
      {showRemove && (
        <ComboboxPrimitive.ChipRemove
          render={<Button variant="ghost" size="icon-xs" />}
          className="size-3 rounded-sm"
          data-slot="combobox-chip-remove"
        >
          <XIcon className="pointer-events-none size-3" />
        </ComboboxPrimitive.ChipRemove>
      )}
    </ComboboxPrimitive.Chip>
  )
}

const comboboxChipInputSizeClasses: Record<ComboboxSize, string> = {
  xs: "h-5",
  sm: "h-5.5",
  md: "h-6.25",
  lg: "h-7",
}

function ComboboxChipsInput({
  className,
  ...props
}: ComboboxPrimitive.Input.Props) {
  const size = useComboboxSize()
  return (
    <ComboboxPrimitive.Input
      data-slot="combobox-chip-input"
      className={cn(
        "h-6.25 min-w-16 flex-1 outline-none",
        comboboxChipInputSizeClasses[size],
        className
      )}
      {...props}
    />
  )
}

function useComboboxAnchor() {
  return React.useRef<HTMLDivElement | null>(null)
}

export {
  Combobox,
  ComboboxInput,
  ComboboxContent,
  ComboboxList,
  ComboboxItem,
  ComboboxGroup,
  ComboboxLabel,
  ComboboxCollection,
  ComboboxEmpty,
  ComboboxSeparator,
  ComboboxChips,
  ComboboxChip,
  ComboboxChipsInput,
  ComboboxTrigger,
  ComboboxValue,
  useComboboxAnchor,
}
